import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.util.*;
public class MiniBank {
    static class Account implements Serializable {private static final long serialVersionUID=1L;private final String accountNumber,ownerName;private long balance;Account(String n,String o,long b){accountNumber=n;ownerName=o;balance=b;}public String toString(){return accountNumber+" "+ownerName+" balance="+balance;}}
    static class StatePersister {static void save(Account[] a,Path p)throws IOException{Files.createDirectories(p.getParent());try(ObjectOutputStream o=new ObjectOutputStream(Files.newOutputStream(p))){o.writeObject(a);}}static Account[] load(Path p)throws IOException,ClassNotFoundException{try(ObjectInputStream i=new ObjectInputStream(Files.newInputStream(p))){return (Account[])i.readObject();}}}
    static class TransactionLog {static void append(Path p,String line)throws IOException{Files.createDirectories(p.getParent());Files.writeString(p,line+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}
    static class ReportGenerator {static String generate(Path dir,Path report)throws IOException{long deposits=0,withdrawals=0;StringBuilder out=new StringBuilder("End-of-day report\n");Files.createDirectories(dir);try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"*.log")){for(Path f:files){for(String line:Files.readAllLines(f)){String[] p=line.trim().split("\\s+");if(p.length>=3){long n=Long.parseLong(p[2]);if(p[0].equals("DEPOSIT"))deposits+=n;else if(p[0].equals("WITHDRAW"))withdrawals+=n;}}BasicFileAttributes a=Files.readAttributes(f,BasicFileAttributes.class);out.append(f.getFileName()).append(" size=").append(a.size()).append(" modified=").append(a.lastModifiedTime()).append('\n');}}out.append("Total deposits: ").append(deposits).append("\nTotal withdrawals: ").append(withdrawals).append("\nNet change: ").append(deposits-withdrawals).append('\n');Files.writeString(report,out.toString());return out.toString();}}
    public static void main(String[] args)throws Exception{Path data=Path.of("data"),logs=data.resolve("logs");Account[] a={new Account("AC0001","Aarav",5000),new Account("AC0002","Diya",2000),new Account("AC0003","Kabir",9000)};StatePersister.save(a,data.resolve("accounts.dat"));System.out.println("Reloaded accounts:");for(Account x:StatePersister.load(data.resolve("accounts.dat")))System.out.println(x);TransactionLog.append(logs.resolve("today.log"),"DEPOSIT AC0001 500");TransactionLog.append(logs.resolve("today.log"),"WITHDRAW AC0002 200");System.out.println(ReportGenerator.generate(logs,data.resolve("report.txt")));}
}
